package io.baozhu.copilot.service; import io.baozhu.copilot.ai.*; import io.baozhu.copilot.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.context.*; import org.springframework.core.env.Environment; import org.springframework.stereotype.Service; import java.util.*; @Service public class CopilotService { private final AiProvider provider; private final CopilotRequestRepository audit; public CopilotService(@Qualifier("heuristicAiProvider")AiProvider fallback,CopilotRequestRepository a,Environment e,ApplicationContext c){AiProvider s=fallback;if("openai".equalsIgnoreCase(e.getProperty("ai.provider"))){try{s=c.getBean("openAiCompatibleProvider",AiProvider.class);}catch(Exception ignored){}}provider=s;audit=a;} public SuggestRulesResponse suggest(SuggestRulesRequest r){var out=new SuggestRulesResponse(provider.name(),r.tableName(),provider.suggestRules(r.tableName(),r.columns(),r.sampleRows(),r.businessDescription()),"data-quality-rules-v1"); audit.save("SUGGEST_RULES",provider.name(),r.tableName(),out); return out;} }